import JSZip from "jszip";
export const templateText = "[FUNCIONARIO]\nnome=João\ncargo=Analista\nsalario=2500\n\n[CONFIGURACOES]\nidioma=pt-BR\nativo=true\nnotificacoes=habilitadas\n";
export const instruction = "Extraia apenas os valores da coluna Salário da planilha e substitua o campo salario no TXT. Gere um arquivo por funcionário, sem modificar as outras configurações.";
export const escapeXml = (value: string) => value.replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;").replace(/"/g, "&quot;");
export type FixtureCell = string | number | null | { value: string; type?: string; formula?: string; style?: number; noCache?: boolean };
export async function xlsxFixture(options: { sheets?: { name: string; rows: FixtureCell[][] }[]; shared?: boolean; date1904?: boolean; customize?: (zip: JSZip) => void } = {}) {
  const sheets = options.sheets ?? [{ name: "Funcionários", rows: [["Nome", "Cargo", "Salário"], ["Maria", "Gerente", 4500], ["Carlos", "Técnico", 3200], ["Ana", "Coordenadora", 5800]] }];
  const zip = new JSZip(), shared: string[] = [];
  zip.file("[Content_Types].xml", `<Types xmlns="http://schemas.openxmlformats.org/package/2006/content-types"><Default Extension="rels" ContentType="application/vnd.openxmlformats-package.relationships+xml"/><Default Extension="xml" ContentType="application/xml"/><Override PartName="/xl/workbook.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.sheet.main+xml"/><Override PartName="/xl/styles.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.styles+xml"/>${options.shared ? '<Override PartName="/xl/sharedStrings.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.sharedStrings+xml"/>' : ""}${sheets.map((_, i) => `<Override PartName="/xl/worksheets/sheet${i + 1}.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.worksheet+xml"/>`).join("")}</Types>`);
  zip.file("_rels/.rels", '<Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships"><Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/officeDocument" Target="xl/workbook.xml"/></Relationships>');
  zip.file("xl/workbook.xml", `<workbook xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main" xmlns:r="http://schemas.openxmlformats.org/officeDocument/2006/relationships"><workbookPr date1904="${options.date1904 ? "1" : "0"}"/><sheets>${sheets.map((sheet, i) => `<sheet name="${escapeXml(sheet.name)}" sheetId="${i + 1}" r:id="rId${i + 1}"/>`).join("")}</sheets></workbook>`);
  zip.file("xl/_rels/workbook.xml.rels", `<Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships"><Relationship Id="styles" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/styles" Target="styles.xml"/>${options.shared ? '<Relationship Id="strings" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/sharedStrings" Target="sharedStrings.xml"/>' : ""}${sheets.map((_, i) => `<Relationship Id="rId${i + 1}" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/worksheet" Target="worksheets/sheet${i + 1}.xml"/>`).join("")}</Relationships>`);
  zip.file("xl/styles.xml", '<styleSheet xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main"><numFmts count="2"><numFmt numFmtId="164" formatCode="&quot;R$ &quot;#,##0.00"/><numFmt numFmtId="165" formatCode="yyyy-mm-dd"/></numFmts><fonts count="1"><font><sz val="11"/><name val="Calibri"/></font></fonts><fills count="2"><fill><patternFill patternType="none"/></fill><fill><patternFill patternType="gray125"/></fill></fills><borders count="1"><border/></borders><cellStyleXfs count="1"><xf numFmtId="0" fontId="0" fillId="0" borderId="0"/></cellStyleXfs><cellXfs count="3"><xf numFmtId="0"/><xf numFmtId="164"/><xf numFmtId="165"/></cellXfs><cellStyles count="1"><cellStyle name="Normal" xfId="0" builtinId="0"/></cellStyles></styleSheet>');
  for (const [sheetIndex, sheet] of sheets.entries()) zip.file(`xl/worksheets/sheet${sheetIndex + 1}.xml`, `<worksheet xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main"><sheetData>${sheet.rows.map((row, ri) => `<row r="${ri + 1}">${row.map((value, ci) => {
    if (value === null) return "";
    const ref = String.fromCharCode(65 + ci) + (ri + 1);
    if (typeof value === "number") return `<c r="${ref}"><v>${value}</v></c>`;
    if (typeof value === "object") return `<c r="${ref}"${value.type ? ` t="${value.type}"` : ""}${value.style === undefined ? "" : ` s="${value.style}"`}>${value.formula === undefined ? "" : `<f>${escapeXml(value.formula)}</f>`}${value.noCache ? "" : `<v>${escapeXml(value.value)}</v>`}</c>`;
    if (options.shared) { const index = shared.push(value) - 1; return `<c r="${ref}" t="s"><v>${index}</v></c>`; }
    return `<c r="${ref}" t="inlineStr"><is><t xml:space="preserve">${escapeXml(value)}</t></is></c>`;
  }).join("")}</row>`).join("")}</sheetData></worksheet>`);
  if (options.shared) zip.file("xl/sharedStrings.xml", `<sst xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main">${shared.map(value => `<si><t xml:space="preserve">${escapeXml(value)}</t></si>`).join("")}</sst>`);
  options.customize?.(zip);
  return zip.generateAsync({ type: "uint8array", compression: "DEFLATE" });
}
